-- 1.1. View: vw_LocationCapacity — S?c ch?a và t?n kho c?a t?ng v? trí kho
CREATE OR ALTER VIEW [dbo].[vw_LocationCapacity]
AS
SELECT 
    l.location_id,
    l.location_code,
    l.max_capacity,
    ISNULL(SUM(b.stock_quantity), 0) AS current_stock,
    l.max_capacity - ISNULL(SUM(b.stock_quantity), 0) AS remaining_capacity
FROM dbo.Warehouse_Locations l
LEFT JOIN dbo.Books b ON b.location_id = l.location_id
GROUP BY l.location_id, l.location_code, l.max_capacity;
GO

-- 1.2. Function: fn_CanFitInLocation — Ki?m tra v? trí kho có d? s?c ch?a
CREATE OR ALTER FUNCTION [dbo].[fn_CanFitInLocation]
(
    @location_id INT,
    @additional_quantity INT
)
RETURNS BIT
AS
BEGIN
    DECLARE @remaining INT;
    DECLARE @result BIT = 0;

    SELECT @remaining = remaining_capacity
    FROM dbo.vw_LocationCapacity
    WHERE location_id = @location_id;

    IF @remaining IS NULL OR @remaining >= @additional_quantity
        SET @result = 1;

    RETURN @result;
END;
GO

