INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (427, N'Ngu?i Ðàn Ông Mang Tên OVE (Tái B?n)', N'Fredrik Backman', N'NXB Tr?', CAST(136000.00 AS Decimal(18, 2)), N'NGU?I ÐÀN ÔNG MANG TÊN OVE - CU?N SÁCH KHI?N TRI?U Ð?C GI? CU?I R?I KHÓC B?n có tin r?ng m?t ông lão c?c c?n, khó tính l?i có th? khi?n b?n roi nu?c m?t vì xúc d?ng? B?n dã bao gi? nghi r?ng lòng nhân ái có th? d?n t? nh?ng con ngu?i tu?ng ch?ng khô khan nh?t? M?t ông lão c?c c?n, m?t con mèo hoang, vài ngu?i hàng xóm phi?n ph?c - t?t c? có th? t?o nên m?t câu chuy?n khi?n b?n b?t khóc? V? TÁC GI? : Fredrik Backman - Hành trình tr? thành nhà Van du?c yêu thích Fredrik Backman (sinh nam 1981) là nhà van, blogger và nhà báo ngu?i Th?y Ði?n. Tru?c khi tr? thành ti?u thuy?t gia, ông t?ng vi?t blog và làm phóng viên cho m?t t? báo d?a phuong. Nam 2012, ông xu?t b?n Ngu?i Ðàn Ông Mang Tên Ove, tác ph?m nhanh chóng tr? thành hi?n tu?ng toàn c?u, l?t top bán ch?y t?i nhi?u qu?c gia. Ông n?i ti?ng v?i l?i vi?t hài hu?c, c?m d?ng và d?y tính nhân van, dua nh?ng câu chuy?n d?i thu?ng tr? nên sâu s?c và dáng nh?. V? D?CH GI? : Hoàng Anh - Ngu?i th?i h?n vào tác ph?m Hoàng Anh là d?ch gi? t?n tâm, mang van h?c th? gi?i d?n g?n hon v?i d?c gi? Vi?t. V?i l?i d?ch trôi ch?y, giàu c?m xúc, anh dã giúp nh?ng câu chuy?n nu?c ngoài tr? nên g?n gui và chân th?c hon. M?t s? tác ph?m d?ch tiêu bi?u: Ngu?i Ðàn Ông Mang Tên Ove - Fredrik Backman Britt-Marie Ðã ? Ðây - Fredrik Backman L?i H?a Lúc Bình Minh - Romain Gary TÓM T?T N?I DUNG SÁCH Ove là m?t ngu?i dàn ông 59 tu?i, s?ng m?t cu?c d?i nghiêm túc, theo nguyên t?c và không thích thay d?i. Ông c?c c?n, khó g?n, th?m chí có v? dáng ghét. Nhung sâu bên trong, Ove là m?t ngu?i dàn ông mang nhi?u n?i dau, d?c bi?t là sau khi m?t di ngu?i v? yêu d?u. Cu?c s?ng c?a Ove d?o l?n khi m?t gia dình tr? chuy?n d?n bên c?nh nhà ông và s? xu?t hi?n c?a con mèo hoang. H? vô tình “xâm nh?p” vào cu?c s?ng don d?c c?a ông, kéo theo nh?ng tình hu?ng d? khóc d? cu?i. D?n d?n, t?m lòng nhân h?u c?a Ove du?c hé l? , ch?ng minh r?ng ngay c? nh?ng ngu?i khép kín nh?t cung có th? m? lòng khi g?p dúng ngu?i. Cu?n sách này cung dã du?c chuy?n th? thành b? phim dình dám v?i s? tham gia c?a Tom Hanks , dã du?c d? c? ? h?ng m?c phim nói ti?ng nu?c ngoài hay nh?t t?i Oscar 2017 . Quy?n sách mang d?n cho d?c gi?: Ch?m d?n c?m xúc – Hài hu?c, c?m d?ng và d?y nhân van. Nhìn cu?c s?ng theo cách khác – Ð?ng sau v? ngoài c?c c?n là m?t trái tim ?m áp. Tình ngu?i gi?n d? nhung sâu s?c – Nh?ng k?t n?i nh? bé có th? thay d?i c? m?t d?i ngu?i. Ch?a lành và truy?n c?m h?ng – Dành cho nh?ng ai t?ng cô don, l?c lõng T?i sao d?c gi? nên d?c? Cu?n sách mang ch?t trào l?ng duyên dáng ki?u B?c Âu nhung cung tràn d?y tính nhân van, dã tr? thành hi?n tu?ng toàn c?u v?i g?n 3 tri?u b?n in bán ra. Sách xu?t b?n b?ng ti?ng Anh vào nam 2013 và l?t vào danh sách Sách bán ch?y nh?t c?a New York Times 18 tháng sau khi xu?t b?n và ? trong danh sách th? 42 tu?n. Ð?c gi? dã s?n sàng bu?c vào th? gi?i c?a Ove. Ch?t don t?i Fahasa ngay nào', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974182375.jpg', 452, 2022, 50, 0, N'Tr?', N'8934974182375', 2, 1, 36, 34, CAST(95200.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (428, N'B? Mua Ð? - ?n B?n K? Ni?m - Bìa C?ng - T?ng Kèm Bookmark + Móc Khoá Balo Mu C?i - Ð?c Quy?n Fahasa', N'Chu Lai', N'CÔNG TY TNHH VAN HÓA VÀ TRUY?N THÔNG TH?O NGUYÊN', CAST(175000.00 AS Decimal(18, 2)), N'Mua Ð? “Mua d?” là ti?u thuy?t c?a nhà van Chu Lai, k?t qu? sau nhi?u nam tran tr? và sáng t?o. Ti?u thuy?t l?y b?i c?nh chính là cu?c chi?n d?u b?o v? Thành c? Qu?ng Tr? mùa hè nam 1972, c? ? hai bên chi?n tuy?n (ta và d?ch), xoay quanh tr?c hai nhân v?t chính: Cu?ng (chi?n si Gi?i phóng) và Quang (tên ch? huy h?c báo c?a ng?y). Bên c?nh dó là b?i c?nh trên bàn dàm phán ? Pa-ri v?i nhân v?t bà m? c?a Cu?ng - m?t nhà ngo?i giao là thành viên c?a doàn dàm phán phía ta… Tác gi? dã mu?n phông n?n c?a m?t s? ki?n l?ch s? di?n hình nhung cung khá “nh?y c?m” trong cu?c kháng chi?n ch?ng M?, c?u nu?c d? d?ng l?i b?c tranh bi tráng v? cu?c chi?n d?u b?o v? Thành c? 81 ngày dêm mùa hè d? l?a nam 1972. B?ng ngòi bút d?m ch?t van miêu t?, không ôm d?m di vào “b? r?ng” c?a không gian cu?c chi?n, mà di vào chi?u sâu c?a nh?ng chi ti?t, nh?ng nhân v?t; l?t t? tính ch?t kh?c li?t và bi tráng, tác gi? nh?p h?n vào t?ng nhân v?t d? giúp b?n d?c th?y du?c tâm tr?ng gi?ng xé trong t?ng c?nh hu?ng: C? s? dung c?m và d?n hèn, cái thi?n và cái á.c,… s? bùng n.? nh?ng tr?ng thái tích c?c và tiêu c?c… c?a nh?ng con ngu?i t?ng giây, t?ng phút ph?i d?i m?t v?i s? hy sinh, ch?t chóc d?n b?t c? lúc nào. Ðan cài trong nh?ng trang miêu t? cu?c chi?n d?c d?n gai ngu?i là nh?ng kho?ng bình yên, lãng m?n d?y ch?t tho c?a tình yêu n?y m?m trong l?a d?n, c?a nh?ng s? hào hoa, phóng túng r?t d?i… (Trích gi?i thi?u trên báo Quân d?i nhân dân dang t?i ngày 29/04/2016)', N'https://cdn1.fahasa.com/media/catalog/product/z/7/z7524933271610_