INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (429, N'Hai M?t C?a Gia Ðình (Tái B?n 2025)', N'Choi Kwanghuyn', N'AZ Vi?t Nam', CAST(104000.00 AS Decimal(18, 2)), N'Hai M?t C?a Gia Ðình T?i sao chúng ta l?i ch?u t?n thuong b?i gia dình – nh?ng ngu?i g?n chúng ta nh?t? T?i sao dù ? c?nh gia dình nhung b?n v?n c?m th?y xa cách và cô don? Vì sao chúng ta luôn b?c phát c?m xúc khi d?ng tru?c gia dình mình. Vì sao n?i dau c?a gia dình noi b?n sinh ra và l?n lên l?i l?p l?i trong gia dình hi?n t?i? Nhi?u khi nh?ng t?n thuong d?n t? gia dình noi chúng ta sinh ra và l?n lên l?i chính là nguyên nhân c?a các v?n d? trong gia dình hi?n t?i. Gia dình tr? thành noi ti?p thêm s?c m?nh và cung là noi khi?n dôi vai chúng ta thêm n?ng triu, là noi ?n náu c?a nh?ng mâu thu?n tinh vi d?ng sau nh?ng phút giây thân m?t, là noi tràn d?y thuong yêu nhung có c? s? ghét b?. Gia dình lúc nào cung có hai m?t nhu v?y. Choi Kwang Huyn – m?t nhà tâm lý h?c hàng d?u Hàn Qu?c, ngu?i dã tham v?n tâm lý cho r?t nhi?u tru?ng h?p có khúc m?c v? t?n thuong tâm lý xu?t phát t? gia dình s? ch? ra nguyên nhân c?a nh?ng t?n thuong, nh?ng n?i dau mà chúng ta ph?i ch?u t? gia dình mình, d?ng th?i dua ra cách gi?i quy?t d?i v?i các v?n d? gia dình nh?c nh?i hi?n t?i. Cu?n sách cho ta cái nhìn m?i v? m?i quan h? gia dình. Qua nh?ng câu chuy?n c?a các gia dình khác nhau, ngu?i d?c l?n lu?t s? th?y du?c s? tuong d?ng và có thêm hi?u bi?t v? nh?ng khái ni?m nhu: ngo?i tình, ch?ng nghi?n m?t di?u gì dó, l?a ch?n ngu?i b?n d?i tuong d?ng, chuy?n di n?i dau…t? dó tìm du?c cách ch?p nh?n và xoa d?u nh?ng t?n thuong trong lòng m?i ngu?i.', N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-1---hai-m_t-c_a-gia-_nh.jpg', 288, 2025, 50, 0, N'Th? Gi?i', N'8935325027482', 3, 1, 37, 8, CAST(72800.00 AS Decimal(18, 2)))
