INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (432, N'B? Thua Ngo?i Con M?i V? - T?ng Kèm Bookmark', N'Lam', N'Skybooks', CAST(84000.00 AS Decimal(18, 2)), N'Thua Ngo?i Con M?i V? “Trong nh?ng tháng ngày l?n lên, có ai dó dã an ?i tôi r?ng: “Khi r?i di, ngu?i thuong c?a b?n s? hóa thành m?t vì sao l?p lánh.” Ngày ?y tôi không thích l?i an ?i dó l?m, vì tôi ch?ng th? tìm du?c vì sao nào trên b?u tr?i thành ph? noi tôi s?ng, dù dêm dó trang có sáng hay không. Mãi sau này tôi m?i hi?u, có nh?ng vì sao không m?c trên b?u tr?i, không th? nhìn b?ng m?t thu?ng, không th? ch?p b?ng di?n tho?i, b?i vì nh?ng vì sao ?y m?c ? trong tim.” Ðó là nh?ng dòng vi?t d?y xúc d?ng trong cu?n sách m?i nh?t c?a tác gi? Lam - “Thua ngo?i con m?i v?”, m?t cu?n sách vi?t v? nh?ng di?u gi?n d? mà thiêng liêng, v? ông bà, gia dình - noi luu gi? nh?ng yêu thuong nguyên so và bình yên nh?t. N?u nhu "Tr?n lên mái nhà d? khóc" dã t?ng ch?m d?n trái tim HÀNG V?N Ð?C GI? b?ng cách ti?p thêm cho chúng ta can d?m d? d?i m?t v?i nh?ng t?n thuong, thì “Thua ngo?i con m?i v?” s? nh? nhàng n?m tay b?n, dua b?n tr? v? v?i mi?n ký ?c êm d?m c?a tu?i tho. Noi có mùi huong ?m áp c?a ông bà, c?a nh?ng b?a com gia dình, c?a ti?ng cu?i giòn tan bên b?p l?a h?ng. Noi mà có l?, m?i chúng ta d?u vô tình lãng quên khi b? cu?n di theo dòng ch?y xô b? c?a th?i gian, ho?c bu?c ph?i r?i xa khi “làm m?t ngu?i tru?ng thành”. Xuyên su?t 216 trang t?n van, Lam d?t nên nh?ng cung b?c c?m xúc v?a g?n gui, v?a l?ng d?ng v? ông bà, gia dình. T?ng câu ch? nhu th?m d?m v? ng?t ngào c?a k?o du?ng tu?i tho, l?i ph?ng ph?t dâu dó v? m?n mòi c?a nh?ng gi?t nu?c m?t chia ly. Ð?c “Thua ngo?i con m?i v?”, ta ch?t nh?n ra r?ng th?i gian có th? làm lu m? nét m?t ngu?i thân yêu, nhung nh?ng k? ni?m quý giá v? gia dình thì v?n luôn v?n nguyên trong tim m?i ngu?i, nhu nh?ng vì sao l?p lánh, soi sáng cho ta trên m?i n?o du?ng d?i. “n?u nhu con bi?t tru?c r?ng s? có m?t ngày con s? l?c mãi mãi hoi ?m m?t bàn tay con s? ôm ch?m l?y n?c n? trong lòng bà d? th?i gian ch?ng th? mang bà c?a con xa.” “Thua ngo?i con m?i v?” mang s? nh? nhàng c?a huong v? tình thân qua t?ng b?a com cùng ông bà bu?i chi?u hè, huong khói can b?p ló r?ng trong lòng b?n, mang m?i phi?n mu?n c?a b?n di xa nhu m?t gi?c ng? êm. Ð? trên hành trình tru?ng thành, n?u có cô don, l?c l?i, b?n v?n có nh?ng h?nh phúc tu?i tho nh? xinh làm di?m t?a, nâng d? dôi chân b?n bu?c di ch?m rãi t?n hu?ng m?ng u?c tu?i tr?, xoa d?u bao n?i bu?n cu?n trào noi l?ng ng?c, d?p tan con n?c n? và v? òa c?a nh?ng dêm t?i trong phòng tr? noi xa… “Thua ngo?i con m?i v?” t?a nhu chi?c ruong ký ?c nh? trong trái tim b?n, ghi l?i nh?ng hoài ni?m d?p d?, d?ng th?i cung là ngu?i b?n d?ng hành d? chúng ta ti?p t?c bu?c di d?n tuong lai. Ð?ng th?i cu?n sách cung là m?t n?t tr?m d? nh?c ta có th? d?ng l?i m?t chút, l?ng nghe ti?ng lòng mình, d? bi?t trân tr?ng hon nh?ng giá tr? bình d? mà thiêng liêng c?a hai ch? “gia dình”. Sau khi khép l?i cu?n sách này c?a Lam, mong b?n nh? nhàng bu?c ti?p hành trình tr? thành “ngu?i l?n” h?nh phúc c?a mình, vì nh?ng ngu?i b?n yêu quý luôn ? bên c?nh b?n không bao gi? r?i xa!', N'https://cdn1.fahasa.com/media/catalog/product/z/5/z5919252030585_22f8867c87aacc0e58cbdba585ca9e1d.jpg', 216, 2024, 50, 0, N'Dân Trí', N'8935325023583', 3, 1, 41, 37, CAST(58800.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (433, N'K? T? T? Ð?c H?i', N'Higashino Keigo', N'1980 Books', CAST(168000.00 AS Decimal(18, 2)), N'K? T? T? Ð?c H?i Cu?n sách là m?t tuy?n t?p truy?n ng?n tr? danh, d?nh cao c?a Higashino Keigo v?i các c?t truy?n hài hu?c, châm bi?m sâu cay và nh?ng tu?ng tu?ng kì quái: Ông ngo?i lên k? ho?ch b?t cóc cháu ru?t; M?t cô gái d?a vào cu?n sách Hu?ng d?n s? d?ng sát ý d? lên k? ho?ch gi?t ngu?i; Cách con ngu?i d?i x? v?i m?t sinh v?t l? có v? ngoài nhu thiên s?, không rõ gi?ng loài, chuyên an nh?a; M?t ngu?i dàn ông gi?t h?i v? mình và mu?n ra t? thú nhung b? m?t cu?n “c?m nang” gây c?n tr?;... M?i câu chuy?n là m?t lát c?t hi?n th?c v?i nh?ng tình ti?t “quay xe” không th? lu?ng tru?c. ?n sau nh?ng ti?ng cu?i dó, tác gi? dã l?ng ghép m?t cách tinh t? nh?ng bài h?c v? con ngu?i, m?i quan h? trong gia dình và các v?n d? xã h?i. M?c l?c: 1. Thiên du?ng b?t cóc 2. Angel 3. Quý bà khéo tay 4. C?m nang c?nh sát 5. C? ông trông nhà 6. Búp bê chú r? 7. N? nhà van 8. Hu?ng d?n s? d?ng sát ý 9. Chu?c l?i 10. Nhân ch?ng hi?n hách 11. Chuong trình giám d?nh v?t ch?ng kinh di?n 12. Vòng quay t?ng ti?n Chuong k?t d?c bi?t: Kyogoku Natsuhiko vs Higashino Keigo Thông tin v? tác ph?m: 1. Ðây là m?t tuy?n t?p truy?n ng?n tr? danh c?a Higashino Keigo, không ph?i theo phong cách trinh thám ly k? quen thu?c, mà là nh?ng câu chuy?n hài hu?c, châm bi?m sâu cay và d?y tu?ng tu?ng k? quái. 2. S? rùng mình pha tr?n v?i ti?ng cu?i – v?a ghê r?n v?a bu?n cu?i d?n d?ng tóc gáy. M?t tuy?n t?p g?m 12 truy?n ng?n d?nh cao v?i ch?t hài den d?c trung, mang l?i n? cu?i d?ng cay nhung d?y th?a mãn! 3. Tính “hài den” châm bi?m d? l?i sau ti?ng cu?i là s? d?ng cay, m?a mai, bùng n? c?a mâu thu?n xã h?i. 4. T?t c? b?i c?nh d?u là nh?ng câu chuy?n xu?t phát t? nh?ng di?u bình thu?ng t? các m?i quan h? gia dình, d?i s?ng, xã h?i, công vi?c, h?c t?p… nhung b? d?y d?n c?c h?n d? b?c l? nh?ng mâu thu?n ti?m ?n. 5. D? dàng c?m nh?n nh?ng nhân v?t v?i ph?n c?m xúc chân th?t nh?t mà ta v?n th?y hàng ngày qua nh?ng v?n d? nh?c nh?i và th?i s? vu?t th?i gian. Trích d?n hay trong sách: - “Ti?ng cu?i là m?t công tác r?t c?ng d?u. Không d? gì mà kích ho?t nó. Nên khi c? g?ng b?t công t?c cu?i lên, ta l?i vô tình ch?m vào công t?c khác…” - “Th?t ra c?m giác sau khi hoàn thành nó (truy?n cu?i) còn th?a mãn hon c? lúc vi?t xong m?t truy?n trinh thám”. - “V? k? thu?t, làm ngu?i ta cu?i khó hon làm ngu?i ta khóc nhi?u.” - “Tôi d?c các truy?n theo th? t?. Ðang d?c vui v? thì l?i b? truy?n dó dánh úp. ‘O, dây là truy?n trinh thám r?i còn gì.’ M?t s? ph?n b?i d? ch?u. Cú b? hu?ng ?y ngu?c l?i r?t thú v?.” Tác gi?: HIGASHINO KEIGO sinh nam 1958 t?i Osaka. T?t nghi?p khoa K? thu?t Ða?i ho?c Công lâ?p Osaka (Osaka Prefecture University). Nam 1985, ông b?t d?u s? nghi?p nhà van v?i tác ph?m Houkago, do?t gi?i thu?ng Edogawa Ranpo l?n th? 31. Nam 1999, ông nh?n gi?i thu?ng Hi?p h?i nhà van trinh thám Nh?t B?n l?n th? 52 cho tác ph?m Himitsu. Nam 2006, ông do?t gi?i thu?ng Naoki l?n th? 134 và gi?i thu?ng Honkaku Mystery l?n th? 6 cho tác ph?m Yougisha X no Kenshin. Nam 2012, ông nh?n gi?i thu?ng Van h?c Công lu?n Trung uong l?n th? 7 cho tác ph?m Namiya Zakka-ten no Kiseki. Nam 2013, ông do?t gi?i thu?ng Shibata Renza-buro l?n th? 26 cho tác ph?m Mugen Hana. Nam 2014, ông nh?n gi?i thu?ng Van h?c Eiji Yoshikawa l?n th? 48 cho tác ph?m Inori no Maku ga Oriru Toki. Nam 2019, ông du?c trao gi?i thu?ng Van hóa Xu?t b?n Noma l?n th? nh?t. Các tác ph?m tiêu bi?u c?a ông bao g?m: Bunshin, Byakuyakou, Genya, Kokushou Shousetsu, lo?t truy?n Masquerade Hotel, Hakuchou to Koumori, Toumei na Rasen và nhi?u tác ph?m khác.', N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia-1-ke-tu-te-doc-hai.jpg', 372, 2025, 50, 0, N'Hà N?i', N'8936230473562', 3, 1, 41, 6, CAST(117600.00 AS Decimal(18, 2)))
