1, 50, 0, N'NXB Th? Gi?i', N'8935251416909', 7, 1, 15, 7, CAST(77700.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (442, N'B? Nghi Giàu & Làm Giàu (Tái B?n 2020)', N'Napoleon Hill', N'FIRST NEWS', CAST(80000.00 AS Decimal(18, 2)), N'Nghi Giàu & Làm Giàu (Tái B?n) - (Tái b?n c?a cu?n "Cách Nghi Ð? Thành Công") NGHI GIÀU VÀ LÀM GIÀU Think and Grow Rich - Nghi giàu và làm giàu là m?t trong nh?ng cu?n sách bán ch?y nh?t m?i th?i d?i. Ðã hon 60 tri?u b?n du?c phát hành v?i g?n tram ngôn ng? trên toàn th? gi?i và du?c công nh?n là cu?n sách t?o ra nhi?u tri?u phú, m?t cu?n sách truy?n c?m h?ng thành công nhi?u hon b?t c? cu?n sách kinh doanh nào trong l?ch s?. Tác ph?m này dã giúp tác gi? c?a nó, Napoleon Hill, du?c tôn vinh b?ng danh hi?u “ngu?i t?o ra nh?ng nhà tri?u phú”. Ðây cung là cu?n sách hi?m hoi du?c d?ng trong top c?a r?t nhi?u bình ch?n theo nhi?u tiêu chí khác nhau - bình ch?n c?a d?c gi?, c?a gi?i chuyên môn, c?a báo chí. Lý do d? Think and Grow Rich - Nghi giàu và làm giàu có du?c vinh quang này th?t hi?n nhiên và d? hi?u: B?ng vi?c d?c và áp d?ng nh?ng phuong pháp don gi?n, cô d?ng này vào d?i s?ng c?a m?i cá nhân mà dã có hàng ngàn ngu?i trên th? gi?i tr? thành tri?u phú và thành công b?n v?ng. Ði?u thú v? nh?t là các bí quy?t này có th? du?c hi?u và áp d?ng b?i b?t k? m?t ngu?i bình thu?ng nào, ho?t d?ng trong b?t c? linh v?c nào. Qua hon 70 nam t?n t?i, nh?ng dúc k?t v? thành công c?a Napoleon Hill d?n nay v?n không h? b? l?i th?i, ngu?c l?i, th?i gian chính là minh ch?ng s?ng d?ng cho tính dúng d?n c?a nh?ng bí quy?t mà ông chia s?. Sinh ra trong m?t gia dình nghèo vùng Tây Virginia, con du?ng thành công c?a Napoleon Hill cung tr?i qua nhi?u thang tr?m. Kh?i d?u b?ng chân c?ng tác viên cho m?t t? báo d?a phuong lúc 15 tu?i, d?n nam 19 tu?i Hill tr? thành nhà qu?n lý m? than tr? tu?i nh?t, sau dó b? ngang d? theo du?i ngành lu?t. Napoleon Hill còn kinh qua nhi?u ngh? nhu kinh doanh g?, xe hoi, vi?t báo v? kinh doanh… Ðó là nh?ng công vi?c ông t?ng n?m tr?i tru?c khi 25 tu?i! Song khác v?i nh?ng ngu?i thành d?t khác, ông c?n th?n phân tích t?ng s? ki?n tr?ng d?i trong d?i mình, rút ra nh?ng bài h?c, r?i ti?p t?c rút g?n chúng thành các nguyên t?c can b?n, t? ch?c các nguyên t?c ?y thành tri?t lý s?ng và rèn luy?n... Co h?i d?c bi?t dã d?n v?i Hill trong m?t l?n ph?ng v?n d? vi?t v? chân dung Andrew Carnegie - ông “vua thép” huy?n tho?i c?a M? dã di lên t? hai bàn tay tr?ng. T? l?n ph?ng v?n dó, Napoleon Hill có d?p ti?p c?n v?i nh?ng con ngu?i thành d?t và có quy?n l?c nh?t t?i M? d? tìm hi?u và h?c h?i nh?ng bí quy?t thành công c?a h?, trong th? so sánh và ki?m ch?ng v?i nh?ng công th?c thành công c?a Andrew Carnegie. Ông mu?n qua dó có th? dúc k?t và vi?t nên m?t cu?n sách ghi l?i nh?ng bí quy?t giúp các cá nhân bình thu?ng thành nh?ng ngu?i thành công trong xã h?i. Ð? th?c hi?n cu?n sách này, Napoleon Hill dành h?u nhu toàn b? th?i gian và công s?c trong su?t g?n ba muoi nam d? ph?ng v?n hon 500 ngu?i n?i ti?ng và thành công nh?t trong nhi?u linh v?c khác nhau, cùng hàng ngàn doanh nhân khác - c? nh?ng k? th?t b?i và nh?ng ngu?i thành công. K?t qu? c?a nh?ng nghiên c?u không m?t m?i dó là Think and Grow Rich - Nghi giàu và làm giàu - công th?c, hay “c?m nang” d? tr? thành vu?t tr?i và du?c xã h?i n? tr?ng. Cu?n sách cung dua Napoleon Hill vào danh sách m?t trong nh?ng tác gi? có tác ph?m bán ch?y nh?t th? gi?i t? tru?c d?n nay. Ðu?c vi?t ra t? vô s? nh?ng câu chuy?n có th?t, tác ph?m có m?t s?c thuy?t ph?c và lay d?ng r?t l?n. B?n không ch? du?c bi?t bí quy?t v? s? thành công c?a các tên tu?i nhu Edison - nhà phát minh l?i l?c mà th?i gian rèn luy?n trong tru?ng h?c ch?… v?n v?n 3 tháng; nhu Henry Ford - ngu?i b? coi là không có h?c v?n nhung dã tr? thành ông trùm trong n?n công nghi?p xe hoi v?i m?t gia tài k?ch xù… mà còn c?a r?t nhi?u cá nhân trong nhi?u linh v?c