INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (449, N'B? Tang T?c Bán Hàng B?ng SPIN (Tái B?n 2024)', N'Neil Rackham', N'CÔNG TY C? PH?N SÁCH OMEGA VI?T NAM', CAST(97000.00 AS Decimal(18, 2)), N'Tang T?c Bán Hàng B?ng SPIN Trong linh v?c qu?n tr? kinh doanh, bán hàng luôn du?c coi là m?t ngh? d?y s?c h?p d?n và thú v?. Có l? vì nhu m?t chuyên gia bán hàng dã nói, h?u nhu chúng ta ai cung ph?i bán m?t cái gì dó. Nhung d? thành công trong bán hàng l?i là vi?c không h? don gi?n. Ðã có r?t nhi?u cu?n sách vi?t v? bán hàng. M?i cu?n l?i ti?p c?n bán hàng theo nh?ng khía c?nh và cách th?c khác nhau. Nhung khác v?i các cu?n sách v? ngh? thu?t bán hàng, Cu?n sách Tang t?c bán hàng b?ng SPIN c?a tác gi? Neil Rackham không nói v? ngh? thu?t bán hàng thông qua các bí kíp mà dua ra mô hình chu?i câu h?i SPIN (vi?t t?t c?a Situation questions, Problem questions, Implication questions, Need-payoff questions hay còn g?i là các câu h?i Tình hình, câu h?i V?n d?, câu h?i G?i ý và câu h?i Chi phí nhu c?u). Cu?n sách Tang t?c bán hàng b?ng SPIN c?a Neil Rackham không ph?i là lý thuy?t sáo r?ng v? cách bán hàng mà là nh?ng nghiên c?u h?t s?c khoa h?c và c? th? c?a Huthwaite – công ty chuyên nghiên c?u v? phuong pháp bán hàng hi?u qu? c?a Neil Rackham. Ð?c Tang t?c bán hàng b?ng SPIN , b?n có th? th?y du?c s? khác nhau gi?a bán hàng quy mô l?n và bán hàng quy mô nh?. B?n cung s? hi?u du?c t?i sao có nh?ng th? thu?t bán hàng có th? thành công v?i các cu?c bán hàng quy mô nh? nhung l?i kém hi?u qu? v?i các cu?c bán hàng quy mô l?n và r?t, r?t nhi?u di?u thú v? khác ch? có th? tìm th?y trong Tang t?c bán hàng b?ng SPIN . Quan tr?ng hon, Tang t?c bán hàng b?ng SPIN còn giúp b?n bi?n lý thuy?t thành nh?ng chi?n lu?c bán hàng hi?u qu? hon. Tang t?c bán hàng b?ng SPIN c?a Neil Rackham là cu?n sách gây du?c r?t nhi?u s? chú ý c?a gi?i bán hàng chuyên nghi?p và c?a nh?ng ai th?t s? coi bán hàng là m?t ngh? thu?t. Thông tin v? tác gi? NEIL RACKHAM n?i ti?ng trên toàn th? gi?i v?i tu cách là di?n gi?, nhà nghiên c?u, dào t?o, vi?t sách v? bán hàng và marketing. Ba trong s? các cu?n sách c?a ông dã l?t vào danh sách bestseller c?a t? The New York Times, và các tác ph?m c?a ông dã du?c d?ch ra trên 50 th? ti?ng. Neil Rackham là ch? t?ch, d?ng th?i là ngu?i sáng l?p công ty Huthwaite, Inc. Công ty c?a ông chuyên nghiên c?u, t? ch?c các bu?i seminar và tu v?n v? bán hàng cho hon 200 doanh nghi?p hàng d?u t?i M? nhu Xerox, IBM, AT&T, Kodak và Citicorp.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935251421668.jpg', 326, 2024, 50, 0, N'Công Thuong', N'8935251421668', 9, 1, 46, 11, CAST(67900.00 AS Decimal(18, 2)))
