INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (458, N'B? Dám Thay Ð?i - T? A Ð?n Z (Tái B?n 2020)', N'Inner Space, Covent Garden', N'FIRST NEWS', CAST(100740.00 AS Decimal(18, 2)), N'Trong cu?n sách này, ngoài vi?c ch? ra nh?ng tâm tr?ng tiêu c?c mà m?i ngu?i v?n luôn ph?i d?i di?n trong cu?c s?ng, hai tác gi? Inner Space và Covent Garden còn cung c?p cho b?n d?c tác h?i mà nh?ng tâm tr?ng tiêu c?c dó mang l?i. Thêm vào dó, Inner Space và Covent Garden cung giúp b?n d?c nh?ng cách th?c d? chuy?n hóa nh?ng thái d? tiêu c?c thành tích c?c. Ch?ng h?n v?i thái d? phàn nàn, hai tác gi? ch? ra: “Phàn nàn phá h?ng tâm tr?ng và tri?t tiêu d?ng l?c c?a ta, cung nhu c?a nh?ng ngu?i khác”. Ð? quên di thái d? phàn nàn, hai tác gi? dua ra l?i khuyên: “Luôn có di?u gì dó d? ta trân tr?ng và bi?t on, ch?ng h?n nhu m?t mái nhà che mua che n?ng hay m?t bu?i bình minh tuy?t d?p”. Nh?ng trích d?n d?c s?c trong cu?n sách: “S? nhàm chán ch? t?m th?i nguôi ngoai trong khi ta m?i mê v?i nh?ng trò tiêu khi?n, nhung ngay khi d?ng cu?c choi, ta l?i roi vào c?m giác chán chu?ng”. “N?i s? cung gi?ng nhu m?t th?i nam châm. N?u c? t?p trung vào n?i s? mo h? nào dó, dù không ch? ý thì b?n cung s? hành d?ng v?i n?i s? hãi, t? dó làm cho nó tr? nên s?ng d?ng y nhu th?t”. “Nh?ng t?n thuong quá kh? c? mãi dai d?ng b?i vì ta liên t?c h?i tu?ng v? chúng. Chính B?N m?i là ngu?i làm cho mình b? t?n thuong”. “Ghen t? thu?ng xu?t phát t? vi?c h? th?p b?n thân và so sánh”.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_226328.jpg', 106, 2020, 50, 0, N'NXB T?ng H?p TPHCM', N'8935086851067', 13, 1, 22, 25, CAST(70518.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (459, N'Ki Nang Vàng Cho H?c Sinh Trung H?c - H?c Cách Qu?n Lí Cu?c S?ng (Tái B?n 2023)', N'Liu Yong', N'Nhà Xu?t B?n Kim Ð?ng', CAST(32000.00 AS Decimal(18, 2)), N'Ki Nang Vàng Cho H?c Sinh Trung H?c - H?c Cách Qu?n Lí Cu?c S?ng Th? gi?i r?ng l?n có bi?t bao di?u ph?c t?p khi?n nh?ng b?n tr? m?i ch?p ch?ng bu?c vào d?i ph?i b?i r?i, ban khoan. Cu?n sách H?c Cách Qu?n Lí Cu?c S?ng c?a Liu Yong mang d?n nh?ng câu chuy?n, bài h?c gi?n d?, g?n gui, giúp các b?n tr? ph?n nào dó th?u hi?u th? nào là tình yêu, bi?t cách ?ng x? v?i th?t b?i, thành công, cùng nh?ng tình hu?ng khó khan khác trong cu?c s?ng. ÐÔI ÐI?U V? TÁC GI? Liu Yong v?a là h?a si, nhà van, v?a là di?n gi? n?i ti?ng, m?t ngu?i s?ng tích c?c, cham ch?, luôn mu?n vu?t qua chính mình. Ông t?ng là h?a si t?i Vi?n B?o tàng Mi thu?t Danville, h?a si chuyên trách t?i Tru?ng Ð?i h?c St.John’s, là Phó giáo su Tru?ng Saint Vincent t?i Mi, là Giáo su th?nh gi?ng c?a Tru?ng Ð?i h?c H? Môn, Trung Qu?c. Cho d?n nay Liu Yong dã xu?t b?n hon m?t tram d?u sách b?ng ti?ng Anh và ti?ng Trung, nh?ng bài lu?n v? cu?c s?ng cùng nh?ng bài t?n van truy?n c?m h?ng ?m áp c?a ông dã tr? thành nh?ng cu?n sách bán ch?y nh?t. Ông cung du?c m?nh danh là “nhà van g?n k?t tâm h?n v?i l?a tu?i thanh thi?u niên”. Ông dã t?ng quyên góp xây d?ng 40 tru?ng ti?u h?c và ông cung là m?t trong s? ít h?a si duong d?i thu?ng xuyên có tranh du?c vào Nhà d?u giá Qu?c t? Sotheby’s. “Ð?c thêm nhi?u sách hon, di nhi?u noi hon, suy nghi nhi?u hon, sáng t?o nhi?u hon, thì b?n càng d? dàng d?n v?i thành công.” - Liu Yong', N'https://cdn1.fahasa.com/media/catalog/product/k/i/ki-nang-vang-cho-hoc-sinh-trung-hoc_hoc-cach-quan-ly-cuoc-song_tb-2023.jpg', 124, 2023, 50, 0, N'Kim Ð?ng', N'8935244895131', 