INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (460, N'S?ng An Vui (Tái B?n 2025)', N'Khangser Rinpoche', N'FIRST NEWS', CAST(36500.00 AS Decimal(18, 2)), N'S?ng An Vui Theo th?ng kê c?a T? ch?c Y t? th? gi?i (WHO), m?i nam trên th? gi?i có hon m?t tri?u ngu?i ch?t vì t? sát. Trung bình, c? 40 giây thì có ngu?i t? k?t li?u d?i mình. Và, t? l? ngu?i t? t? dã tang 60% trong 45 nam qua. D? báo, d?n nam 2020, c? sau 20 giây s? có m?t ngu?i ch?t vì nguyên nhân này – m?t con s? kh?ng khi?p. Cung theo WHO, hon 90% ngu?i ch?t vì t? sát m?c b?nh r?i lo?n tinh th?n t?i th?i di?m h? qua d?i, và nguyên nhân hàng d?u d?n d?n t? sát là ch?ng tr?m c?m lâu ngày không du?c di?u tr?. Chua bao gi?, gi?i t?a nh?ng c?m xúc tiêu c?c nhu cang th?ng, bu?n bã, s? hãi… l?i tr? nên c?p bách nhu hi?n t?i. “Tru?c dây kho?ng 15 nam, m?t ngu?i em h? g?i di?n cho tôi và nói có m?t ngu?i b?n dang tr?i qua cang th?ng và b?t an. Em h?i tôi có th? giúp b?n c?u ?y hay không. Lúc dó, tôi dang b?n và b?o em tôi hãy dua b?n c?u ?y d?n g?p tôi sau. M?t tu?n sau dó, c?u b?n ?y dã t? sát. Tôi b? s?c và vô cùng bu?n bã. Tôi dã có th? giúp c?u ?y n?u tôi có th?i gian g?p c?u ?y s?m hon”, thi?n su Khangser Rinpoche, ti?n si ph?t h?c d?n t? ?n Ð? chia s?. Sau câu chuy?n dau lòng này, ông dành th?i gian nghiên c?u sâu v? co ch? c?a s? cang th?ng. Càng nghiên c?u, ông càng nh?n ra gi?i t?a cang th?ng không quá khó khan. Ðó cung chính là d?ng l?c d? thi?n su b?t tay vào th?c hi?n t?p sách S?ng An Vui, v?i mong mu?n dây s? là chìa khóa d? vu?t qua s? hãi, d?i tr? v?i nh?ng sân si, gi?n d? trong lòng. Cung c?p cho ngu?i d?c nh?ng ki?n th?c chi ti?t v? nh?ng di?n bi?n n?i tâm, quy?n sách nh? này giúp ngu?i d?c nh?n ra nh?ng y?u t? d? s?ng d?i h?nh phúc nhu: C?n có d?ng l?c s?ng; Th?u hi?u quy lu?t t? nhiên; Ki?m soát lòng tham; Ð?i tr? phi?n não…. Tám y?u t? mà tác gi? d? c?p là b?n th?ng kê tuong d?i d?y d? nhu c?u d? m?t con ngu?i có th? tìm du?c bình an trong tâm tu?ng. Không d?ng l?i ? dó, v?i nh?ng ngu?i dang vu?ng nh?ng c?m xúc tiêu c?c, t?p sách này s? là c?m nang th?c hành gi?i stress hi?u qu?. T?ng bài t?p thanh l?c, rèn luy?n, ti?p nang lu?ng tích c?c cho co th? mà thi?n su dua ra khá c? th?, kèm theo hình minh h?a chi ti?t d? b?n d?c có th? th?c hành, luy?n t?p t?i nhà. Ðáng chú ý, không ch? thiên v? d?i s?ng tâm lý, sách còn có nh?ng bài t?p h? tr? các co quan n?i t?ng. Nghia là, giúp co th? kh?e m?nh c? v? v?t lý. B?i, co th? kh?e m?nh s? là ch? d?a t?t nh?t cho vi?c v?c d?y tinh th?n. Van phong gi?n d?, g?n gui… d?c gi? nhu dang du?c trò chuy?n, tâm tình v?i m?t chuyên gia, v?i ngu?i d?n d?t mình ch?m d?n b?n bình yên. Nhu l?i thi?n su Khangser Rinpoche, khi tâm cang th?ng, b?t an du?c ngan ch?n và gi?i t?a k?p th?i, chúng ta không nh?ng tìm du?c bình an và h?nh phúc n?i t?i mà còn có th? lan t?a ni?m vui s?ng t?i gia dình và c?ng d?ng xung quanh. Ðây cung là nh?ng gì b?n d?c có th? nh?n du?c t? t?p sách này.', N'https://cdn1.fahasa.com/media/catalog/product/-/1/-1740566419.jpg', 100, 2025, 50, 0, N'H?ng Ð?c', N'8935086858974', 13, 1, 49, 25, CAST(25550.00 AS Decimal(18, 2)))
