INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (462, N'C?m Nang Tu Duy Ð?o Ð?c', N'Richard Paul , Linda Elder', N'NXB T?ng H?p TPHCM', CAST(24000.00 AS Decimal(18, 2)), N'B? sách C?M NANG TU DUY này dành cho m?i b?n d?c, t? h?c sinh, sinh viên d?n các gi?ng viên, các nhà nghiên c?u, doanh nhân, ngu?i dã di làm cung nhu quý ph? huynh... mu?n nâng cao nang l?c tu duy c?a mình. H?c sinh, sinh viên có th? d?c c?m nang nhu tài li?u tham kh?o d? h?c t?t các b? môn; quý ph? huynh có th? s? d?ng c?m nang d? v?a nâng cao nang l?c tu duy c?a mình v?a giúp con em mình phát tri?n các k? nang tu duy c?n thi?t d? h?c t?t; các gi?ng viên, nhà nghiên c?u có th? s? d?ng c?m nang d? h?c t?t; các ch? d? c?a mình; ngu?i dã di làm, doanh nhân... có th? áp d?ng các k? nang, ý tu?ng c?a c?m nang vào công vi?c và cu?c s?ng. B? sách do “The Foundation for Critical Thinking (Qu? Tu duy Ph?n bi?n) biên so?n. Ðây là m?t t? ch?c h?c thu?t, cung c?p nhi?u “c?m nang” v? tu duy khoa h?c du?c biên so?n ch?t ch?, ch?t l?c, ng?n g?n và thi?t th?c, dúc k?t nhi?u thành t?u v? phuong pháp trên “m?u s? chung” là khuy?n khích tu duy phân tích và ph?n bi?n, cùng v?i các k? nang nghe, nói, d?c, vi?t, h?c t?p, và nghiên c?u m?t cách có th?c ch?t, có chi?u sâu và d? dàng áp d?ng vào cu?c s?ng.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_119074.jpg', 88, 102016, 50, 0, N'NXB T?ng H?p TPHCM', N'9786045856611', 13, 1, 49, 33, CAST(16800.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (463, N'Ti?n Trình Thành Nhân (Tái B?n 2024)', N'Carl R. Rogers', N'Bách Vi?t', CAST(108500.00 AS Decimal(18, 2)), N'Ti?n Trình Thành Nhân (Tái B?n 2024) Carl R. Roger sinh ngày 8/1/1902, t?i Oak, M?. Ông là con th? trong m?t gia dình theo Tin Lành nghiêm kh?c. Gia dình ông có trang tr?i r?ng, cùng v?i lòng say mê nghiên c?u khoa h?c nên không khó hi?u khi ông theo h?c ngành Canh nông t?i Ð?i h?c Wisconsin. Sau khi t?t nghi?p d?i h?c, ông quy?t d?nh h?c ? Ch?ng vi?n Union Theologial Seminary nam 1924. T?i dây ông b? h?p d?n b?i các bài thuy?t gi?ng v? tâm lý và tâm lý tr? li?u. Sau dó ông chuy?n t?i tru?ng Su ph?m thu?c d?i h?c Columbia. Nam 1931, ông nh?n b?ng tâm lý h?c giáo d?c và lâm sàng. Ông gi?ng d?y t?i d?i h?c Rochester t? nam 1935 và d?n nam 1940 tr? thành giáo su tâm lý h?c lâm sang t?i Ð?i h?c bang Ohio. T?i dây, ông có bài phát bi?u d?u tiên v? h?c thuy?t phát tri?n m?i và xây d?ng phuong pháp ti?p c?n thân ch? mà ngày nay g?i là Li?u pháp l?y thân ch? là tr?ng tâm. Carl R. Rogers du?c coi là m?t trong nh?ng nhà tâm lý h?c có ?nh hu?ng nh?t th? k? 20. Li?u pháp Thân ch? Tr?ng tâm (Client-centered) c?a ông là m?t li?u pháp theo tru?ng phái Nhân van, t?p trung vào cá nhân thân ch? (person-centered counseling). ? dó nhà tâm lý dóng vai trò là ngu?i hu?ng d?n và h? tr? d? thân ch? t? tr? l?i du?c nh?ng câu h?i c?a mình. Rogers nh?n ra r?ng thân ch? chính là ngu?i bi?t rõ du?c di?u gì dã làm nên nh?ng t?n thuong và các v?n d? noi h?. Trong phòng tr? li?u, Rogers t?o ra m?t b?u không khí c?i m?, an toàn, xây d?ng m?i tuong giao hòa h?o, dáng tin c?y, chân th?t gi?a nhà tr? li?u v?i thân ch?. Ông nh?n m?nh vào s? th?u c?m, chân thành và ch?p nh?n m?i di?u t? thân ch? v?n nhu là mà không phán xét. Ông d?t ni?m tin m?nh m? vào kh? nang t? thay d?i và ch?a lành ? bên trong m?i con ngu?i. GI?I THI?U V? CU?N SÁCH “M?i chúng ta có th? là m?t m?nh v? gi?a d?i này, chính chúng ta cung v? làm muôn m?nh. Nhung xin b?n hãy nh?, luôn có nh?ng gi?t vàng quý giá giúp b?n hàn g?n nh?ng m?nh v? ?y, d? m?t ngày, b?n tr? nên v?n toàn hon bao gi? h?t. T? gi?a nh?ng dau thuong kh?n khó c?a d?i, b?n luôn t?a sáng l?p lánh” Trong tâm tu?ng sinh viên khoa Tâm lí, d?c Ti?n Trình Thành Nhân ch?ng nh?ng là ni?m t? hào d? h? h? khoe ng?m v?i b?n bè, mà còn là m?c tiêu ph?n d?u d?y quy?n ru không d? d?t t?i ngay t?p l?. V?i nh?ng ai ít nhi?u tr?i nghi?m trong linh v?c cham sóc s?c kho? và làm k? tr? giúp nói chung, các ph?m ch?t nhân cách nhà tr? li?u mà Carl Rogers kh?i phát hon n?a th? k? qua v?n ti?p t?c g?i m? nhi?u di?u dòi bu?c ph?n t?nh, thay d?i, d?ng xây và phát tri?n, không ch? ki?n th?c, ki nang mà bao g?m c? d?o d?c nhân van l?n thành t?u tuong tác liên nhân k?t h?p d?a trên c? n?n t?ng khoa h?c và ngh? thu?t. V?i nh?ng ai dang tìm ki?m câu tr? l?i khi b?n thân dang tr?i qua giai do?n kh?ng ho?ng tu?i dôi muoi, Ti?n Trình Thành Nhân c?a Carl Rogers nhu ngu?i b?n l?n tâm tình bao chuy?n ban so, ng? khô khan xa l? mà r?t ráo, l?i vô cùng thân thi?t. Ti?n Trình Thành Nhân vô hình trung, thi?t th?c giúp d? chính h? bu?c vào con du?ng t? giáo d?c: Nh?n chân s? th?t c?a riêng mình, d?nh hình tính cách và t? dól?n h?i th?u hi?u v? ý nghia và m?c dích s?ng ? d?i. CU?N SÁCH MANG Ð?N CHO B?N ÐI?U GÌ? Cu?n sách này không ch? dành cho nh?ng nhà tr? li?u, hon h?t, nó dành cho m?i ngu?i trong chúng ta, dang trên hành trình Tr? thành m?t con ngu?i - M?t b?n th? t? do và toàn v?n, m?t cá nhân d?c l?p & sáng t?o. Ðây là cu?n sách s? cho b?n nh?ng ch? d?n d?: - Ð?n g?n hon và g?n hon n?a v?i n?i tâm mình, dù cho là khó khan hay kh? dau, dù cho kh?e m?nh hay t?t b?nh, dù b?t k? hoàn c?nh nào chang n?a. - Th?c hi?n nh?ng m?i tuong giao gi?a ngu?i v?i ngu?i m?t cách chân thành, ?m áp và h?u hi?u, giúp cho s? tru?ng thành c?a m?i ngu?i. - Tìm ra con du?ng di tích c?c d? phát tri?n nhân cách, hàn g?n nh?ng v?t thuong và tr? thành m?t con ngu?i toàn v?n, t?a sáng. Nh? nhé, dù cho b?n là ai, dã t?ng tr?i qua di?u gì, b?n ? dâu, luôn có nh?ng gi?t vàng quý giá giúp b?n hàn g?n nh?ng m?nh v? tâm h?n và trong b?n luôn có m?t ngu?n sáng ch? l?i d?n du?ng d?n m?t tuong lai d?p d?.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044908144.jpg', 456, 2024, 50, 0, N'Ph? N? Vi?t Nam', N'9786044908144', 14, 1, 29, 9, CAST(75950.00 AS Decimal(18, 2)))
