INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (468, N'B? 1001 Bí Quy?t Dành Cho Tu?i H?c Trò - Hu?ng D?n S? D?ng Tình B?n', N'Hoàng Anh Tú', N'Ðinh T?', CAST(51750.00 AS Decimal(18, 2)), N'“B?n là ngu?i vuon ra tìm tay ta và ch?m d?n trái tim ta.” B?n bè là không th? thi?u, là ngu?n ánh sáng vô t?n cho tâm h?n chúng ta. Nhung nhi?u khi k?t b?n l?i không d? chút nào, nh?t là khi ta là ngu?i hu?ng n?i ch?ng h?n? R?i khi dã làm b?n r?i mà ch?ng may xích mích, gi?n nhau thì làm th? nào? Và n?u ngu?i b?n dó ph?n b?i, b? roi ta h?t l?n này d?n l?n khác thì ph?i x? lý ra sao? Chúng ta ph?i làm nhu th? nào d? tình b?n s? “nhân dôi ni?m vui và chia s? n?i bu?n”, ch? không ph?i xóa tan ni?m vui và làm lòng ta n?ng triu? Trong cu?n sách này b?n s? tìm th?y toàn b? nh?ng “c?m nang” c?n thi?t d? “s? d?ng” tình b?n d?y! Làm sao d? “s? d?ng” tình b?n m?t cách h?u hi?u nh?t, d? choi v?i b?n th?t vui, d? du?c chia s? n?i bu?n cùng b?n, d? trái tim th?c s? k?t n?i d?n trái tim và tình b?n tr? nên b?n ch?t? Ngoài ra còn là cách làm th? nào d? k?t thúc m?t tình b?n (di?u mà hy v?ng b?n s? c?c k? hi?m khi ph?i th?c hi?n), b?i vì không ph?i ngu?i b?n nào cung s? di cùng ta d?n h?t cu?c d?i.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_223383.jpg', 152, 2021, 50, 0, N'NXB Hà N?i', N'8935212353410', 15, 1, 23, 24, CAST(36225.00 AS Decimal(18, 2)))
