INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (470, N'Tâm Lý H?c Ð?ng Hành - Bu?c Cùng Con, Ð?ng Bu?c Thay Con - Ð?ng Hành D?y Con Ðúng Cách Thông Qua 36 Câu Chuy?n Th?c T?', N'Nh?c Hi?u Ðông', N'Công ty TNHH Ecoblader', CAST(132000.00 AS Decimal(18, 2)), N'Tâm Lý H?c Ð?ng Hành - Bu?c Cùng Con, Ð?ng Bu?c Thay Con - Ð?ng Hành D?y Con Ðúng Cách Thông Qua 36 Câu Chuy?n Th?c T? Nuông chi?u thì d?, yêu thuong m?i khó. Áp d?t thì d?, d?ng hành m?i khó. Nhung là cha m?, b?n ph?i làm du?c. B?n dành nhi?u th?i gian cho con, nhung li?u b?n có th?c s? d?ng hành dúng cách? Nhi?u b?c cha m? luôn ? bên con, nhung l?i thi?u s? hu?ng d?n vào nh?ng th?i di?m quan tr?ng. H? lo cho con t?ng b?a an, gi?c ng?, chuy?n h?c, chuy?n choi, dù có th? con không h? yêu c?u. H? nghi r?ng s? quan tâm ?y là tr?n v?n. Nhung d?n khi con th?c s? c?n cha m?—khi g?p mâu thu?n v?i b?n bè, hay ph?i d?i m?t v?i nh?ng thay d?i tâm lý tu?i m?i l?n—thì cha m? l?i lúng túng, né tránh, ho?c th?m chí g?t di. Và r?i, h? t? h?i: T?i sao mình hy sinh nhi?u nhu v?y mà con l?i không th?u hi?u? B?i vì d?ng hành không ph?i là ki?m soát, không ph?i là làm thay, mà là hu?ng d?n và trao quy?n. B?n không th? mãi n?m tay con, nhung có th? cho con dôi chân v?ng vàng d? t? bu?c di. M?i khi b?n làm giúp con m?t vi?c, b?n dang l?y di co h?i d? con t? h?c h?i. Thay vì ch? giúp con gi?i bài t?p, hãy d?y con cách tu duy. Thay vì b?o v? con kh?i m?i th?t b?i, hãy d?y con cách d?ng lên sau v?p ngã. B?n không th? d?y m?t d?a tr? 15 tu?i theo cách b?n d?y khi con 5 tu?i. N?u b?n c?m th?y khó khan khi d?ng hành cùng con, thì dó là d?u hi?u con dang tru?ng thành—và chính b?n cung c?n tru?ng thành cùng con. Quy?n sách này s? giúp b?n làm du?c di?u dó.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043464269.jpg'