INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (484, N'K? Chuy?n Cu?c Ð?i Các Thiên Tài - Louis Pasteur - Th?y Thu?c Vi Ð?i C?a Nhân Lo?i', N'Rasmus Hoài Nam', N'Tân Vi?t', CAST(32000.00 AS Decimal(18, 2)), N'K? Chuy?n Cu?c Ð?i Các Thiên Tài - Louis Pasteur - Th?y Thu?c Vi Ð?i C?a Nhân Lo?i Chua bao gi? chính th?c theo h?c y khoa, nhung Louis Pasteur v?n du?c coi là m?t th?y thu?c vi d?i b?i nh?ng dóng góp to l?n c?a ông cho y h?c. Có th? kh?ng d?nh r?ng, hi?m có ngu?i c?u s?ng du?c nhi?u sinh m?ng hon Louis Pasteur. Nh?ng v?c-xin ông phát tri?n cho d?n nay v?n ti?p t?c c?u s?ng và b?o v? hàng tri?u ngu?i trên th? gi?i. Nh?ng nghiên c?u c?a ông v? vi trùng dã cách m?nh hóa y t?. Louis Pasteur - Th?y thu?c vi d?i c?a nhân lo?i là cu?n sách k? v? câu chuy?n cu?c d?i c?a nhà khoa h?c Louis Pasteur. Cu?n sách mang d?n cho b?n d?c thêm nh?ng góc nhìn r?t m?i v? ông - m?t c?u bé s?ng tình c?m và ham h?c, m?t tu?i tr? dám d?n thân h?t mình cho dam mê, m?t nhà khoa h?c không ng?ng c?ng hi?n cho nhân lo?i d?n t?n nh?ng ngày cu?i d?i. Trên hành trình khoa h?c ?y c?a ông không ch? có nh?ng vinh quang, mà có c? nh?ng cay d?ng, khó khan, nh?ng s? hi sinh l?ng th?m d? theo du?i dam mê khoa h?c c?a cu?c d?i mình. Hon 70 nam cu?c d?i là hon 70 nam nhà khoa h?c Louis Pasteur s?ng vinh quang, không ng?ng n? l?c, toàn tâm toàn ý nghiên c?u c?ng hi?n cho nhân lo?i. Ông là m?t nhà bác h?c vi d?i, du?c nhân lo?i muôn d?i tôn vinh và kính tr?ng. Ông du?c vinh danh là v? ân nhân c?a toàn nhân lo?i. Thông tin v? Louis Pasteur Louis Pasteur (27/12/1822 - 28/9/1895) là nhà sinh h?c, nhà vi sinh v?t h?c, nhà hóa h?c và là m?t giáo su, bác si n?i ti?ng ngu?i Pháp. Ông dã khám phá v?c-xin phòng b?nh d?i, v?c-xin b?nh than, v?c-xin b?nh t?.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935210307347.jpg', 104, 2023, 50, 0, N'Thanh Niên', N'8935210307347', 27, 1, 1, 38, CAST(22400.00 AS Decimal(18, 2)))
