INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (502, N'B? L?y Nu?c Ðu?ng Xa (Tái B?n)', N'Linda Sue Park', N'Thái Hà', CAST(80000.00 AS Decimal(18, 2)), N'L?y Nu?c Ðu?ng Xa (Tái B?n) L?y nu?c du?ng xa - Cu?n ti?u thuy?t d?a trên m?t câu chuy?n có th?t t?i Châu Phi. Hai câu chuy?n dan xen nhau k? v? hai d?a tr? t?i Sudan – s?ng ? hai th?i k? khác nhau – hai b? t?c d?i l?p nhau và hai cu?c “d?u tranh” không gi?ng nhau. Câu chuy?n th? nh?t, Nya là m?t cô bé mu?i m?t tu?i (nam 2008). Cô bé ph?i di b? m?i ngày 8 ti?ng d? l?y nu?c t? m?t chi?c ao b? ô nhi?m. Cô bé không có th?i gian cho tru?ng h?c, cho vui choi, cho t?t c? nh?ng di?u mà h?u h?t các cô gái nh? d?u tr?i qua. Cho d?n m?t ngày n?, nh?ng ngu?i l? vào làng c?a h? d? dào gi?ng và xây tru?ng h?c. Câu chuy?n th? hai, Salva là c?u bé 11 tu?i di b? xuyên l?c d?a Châu Phi d? tìm th?c an, gia dình và m?t noi trú ?n. Ðó là nam 1985 khi Salva dang di h?c và chi?n tranh n? ra. Salva ph?i bang qua sa m?c d? d?n m?t tr?i t? n?n ? Ethiopia. Sau m?t th?i gian dài ? l?i, Salva m?t l?n n?a bang qua sa m?c d? d?n Kenya. Trên ch?ng du?ng dài ?y nhi?u ngu?i dã không vu?t qua du?c. H? ch?t vì dói, vì b? thú d? và binh lính t?n công. Salva là s? ít ngu?i còn s?ng sót và du?c m?t gia dình ngu?i M? nh?n nuôi. Câu chuy?n c?a Nya và Salva dã giao thoa và k?t n?i v?i nhau. Nya k?t thúc hành trình 8 ti?ng m?i ngày di l?y nu?c cho gia dình và du?c d?n tru?ng h?c. Còn hành trình c?a Salva thì v?n ti?p t?c v?i m?t di?n bi?n khác nhi?u ý nghia và tuoi sáng hon!', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935280910737.jpg', 160, 2022, 50, 0, N'NXB Lao Ð?ng', N'8935280910737', 27, 1, 60, 39, CAST(56000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (503, N'Donald J.Trump - Ðã Ð?n Lúc Ph?i C?ng R?n Ð? Khôi Ph?c S? Vi Ð?i C?a Nu?c M? (Tái B?n 2024)', N'Donald J. Trump', N'Alpha Books', CAST(110000.00 AS Decimal(18, 2)), N'Donald J.Trump - Ðã Ð?n Lúc Ph?i C?ng R?n Ð? Khôi Ph?c S? Vi Ð?i C?a Nu?c M? ?ng c? viên t?ng th?ng c?a Ð?ng C?ng hòa trong mùa tranh c? 2016 Donald J. Trump lên k? ho?ch làm cho nu?c M? vi d?i tr? l?i nhu xua. B?i theo Trump, T?ng th?ng Obama là m?t th?m h?a d?i v?i d?t nu?c này. Ông ta dã phá tung n?n kinh t?, m? c?a biên gi?i cho nh?ng tên t?i ph?m b?o l?c bu?c vào, thòng lên vai con cháu chúng ta gánh n?ng n? n?n và di kh?p th? gi?i xin l?i cho nu?c M? nhu th? d?t nu?c vi d?i nh?t th? gi?i này c?n xin l?i vì là m?nh d?t c?a co h?i và t? do nhu tru?c khi Obama tr? thành T?ng th?ng. Gi? dây, nu?c M? trông nhu m?t d?t nu?c ki?t qu?, b? tu?c m?t vi?c làm, s? th?nh vu?ng, s? tôn tr?ng. Và T?ng th?ng Obama làm gì v?i hi?n tr?ng này? Ông ta choi bài t? t? v?i chính nh?ng chính ph? nu?c ngoài dang háo h?c nhìn nu?c M? b? thiêu thành tro. Chuy?n này không th? ti?p di?n. Và n?u Donald Trump có gì d? nói v? chuy?n này, thì dó là nó ph?i k?t thúc. Trong cu?n sách bestseller c?a New York Times, Trump dua ra nh?ng câu tr? l?i mà nu?c M? dang tìm ki?m nhu: - Làm sao d? d?m b?o an ninh biên gi?i và ch?n dòng ngu?i nh?p cu ? ?t vào M?. - Làm sao d? t?o ra vi?c làm cho ngu?i M? b?ng cách bu?c Trung Qu?c ph?i ti?n hành ho?t d?ng m?u d?ch th?t s? công b?ng. - Làm sao d? tr? d?t n? mà không de d?a các chuong trình lâu d?i nhu An sinh Xã h?i, Cham sóc Y t? và Tr? giúp Y t? mà hàng tri?u ngu?i M? dang ph?i s?ng d?a vào. - Làm sao d? s?a d?i s? gian trá c?a h?c thuy?t kinh t? Obama và th?m h?a Obamacare. Th?ng th?n, gay g?t và h?p d?n t? d?u d?n cu?i, cu?n sách v?ch ra m?t ngh? trình d?a trên hi?u bi?t thông thu?ng d? khôi ph?c s? th?nh vu?ng c?a nu?c M? và khi?n d?t nu?c này tr? l?i v?i v? trí d?n d?u th? gi?i. "Tôi yêu nu?c M?. Tôi bu?n lòng tru?c nh?ng gì m?t th?y dang x?y ra trên d?t nu?c mình. Chúng ta dang b? nh?o báng, b? d?y vòng quanh, b? b?t kính và b? d?i x? tàn t?. Obama là m?t thí nghi?m t? khuynh th?t b?i và tr? nên c?c k? sai l?m, và dó là di?u ai cung bi?t. Ngay c? nh?ng ngu?i b?n tôi t?ng b? phi?u cho ngu?i dàn ông này cung th?a nh?n riêng r?ng ông ta là m?t n?i th?t v?ng to l?n. Chúng ta không d? s?c ch?u d?ng b?a b?n này thêm b?n nam n?a. Tuong lai c?a con cháu chúng ta dang lâm nguy - và chúng ta ph?i vì chúng mà kh?c ph?c chuy?n này. Chúng ta ph?i c?ng r?n d? d?t nu?c c?a chúng ta có th? tr? l?i vi d?i nhu xua." Donald Trump', N'https://cdn1.fahasa.com/media/catalog/product/d/a/da-den-luc-phai-cung-ran.u547.d20161215.t090546.604305.jpg', 272, 2024, 50, 0, N'Th? Gi?i', N'8935251422177', 28, 1, 2, 7, CAST(77000.00 AS Decimal(18, 2)))
