INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (506, N'D?u Và Máu - Bìa C?ng', N'Bradley Hope, Justin Scheck', N'CÔNG TY C? PH?N SÁCH OMEGA VI?T NAM', CAST(212000.00 AS Decimal(18, 2)), N'D?u Và Máu D?u và máu không ch? là m?t cu?n sách don thu?n v? chính tr? và kinh t?, mà còn là m?t tác ph?m van h?c, là m?t câu chuy?n tuy?t v?i v? quy?n l?c, tham v?ng và nh?ng bi?n d?ng c?a th? gi?i hi?n d?i. Ð?i v?i d?c gi?, cu?n sách này là m?t c?a s? m? ra m?t th? gi?i m?i, m?t co h?i d? hi?u rõ hon v? nh?ng s?c m?nh và mâu thu?n d?a chính tr? dang d?nh hình th? gi?i xung quanh chúng ta. Cu?n sách cung làm cho d?c gi? hi?u hon v? m?t Trung Ðông phát tri?n v? kinh t? và dang d?n d?c l?p v? chính tr? noi tôi cung dã có d?p ghé tham và làm vi?c lâu dài. - Ð?i s? Tr?n Ng?c Th?ch, Nguyên Ð?i s? Vi?t Nam t?i Các Ti?u vuong qu?c ? R?p Th?ng nh?t D?u và Máu dã m? cánh c?a hi?u bi?t t?i v?i th? gi?i kín dáo và quy?n l?c ?-r?p Xê-út thông qua nhân v?t trung tâm – Th? tu?ng, Thái t? Mohammed Bin Salman. T? nh?ng kho?n d?u tu kh?ng l? vào công ngh?; s? d?ng d?u m? nhu m?t vu khí kinh t?; cho d?n nh?ng c?i cách m?nh m? trong nu?c... Cu?n sách dã cung c?p cái nhìn v? s? n?i lên c?a Th? tu?ng, Thái t? Mohammed Bin Salman. Ði?u gì dã dua v? thái t? sinh nam 1985 không ch? nhanh chóng n?m b?t quy?n l?c t?i ?-r?p Xê-út, mà gi? dây dã tr? thành m?t trong nh?ng nhân v?t chính tr? và kinh t? quan tr?ng nh?t th? gi?i? N?i dung cu?n sách v?n còn có nh?ng di?u gây tranh cãi. Nhung dây là tác ph?m không th? thi?u cho nh?ng ai mu?n hi?u rõ hon v? s?c m?nh, s? tham v?ng, và tuong lai c?a ?-r?p Xê-út du?i th?i Mohammed bin Salman. - Lê Anh Phuong, Tru?ng Co quan Thu?ng trú VTV t?i Trung Ðông', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935251419948.jpg', 378, 2024, 50, 0, N'Th? Gi?i', N'8935251419948', 28, 1, 2, 11, CAST(148400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (507, N'B? H?i Ký Lý Quang Di?u - T?p 2: T? Th? Gi?i Th? Ba Vuon Lên Th? Nh?t (Tái B?n 2023)', N'Lý Quang Di?u', N'Alpha Books', CAST(391000.00 AS Decimal(18, 2)), N'H?i Ký Lý Quang Di?u - T?p 2: T? Th? Gi?i Th? Ba Vuon Lên Th? Nh?t Lý Quang Di?u dã vi?t b? h?i ký dài hai t?p: T?p 1 – “Câu chuy?n Singapore” – trình bày quan di?m c?a ông v? l?ch s? Singapore cho d?n khi tách r?i kh?i Malaysia nam 1965, và t?p 2 – “T? th? gi?i th? ba vuon lên th? nh?t” – thu?t l?i s? chuy?n d?i c?a Singapore d? tr? mình t? d?t nu?c nghèo kh? thành m?t “Con r?ng châu Á”. Sau khi lãnh d?o d?t nu?c Singapore d?c l?p ? cuong v? Th? tu?ng trong vòng 3 th?p k?, nam 1990, Lý Quang Di?u lui v? làm c? v?n và dành nhi?u tâm s?c thu th?p tài li?u d? vi?t nên b? h?i ký này, nhìn l?i toàn b? cu?c d?i ông. Cu?n t?p 1 – Câu chuy?n Singapore – du?c b?t d?u vi?t t? nam 1994, và xu?t b?n l?n d?u tiên nam 1998, k? l?i nh?ng ký ?c dáng t? hào c?a m?t chàng sinh viên gi?i trong nh?ng ngày tháng du h?c trên d?t Anh; t? câu chuy?n tình yêu c?m d?ng c?a ông v?i ngu?i v?, d?n nh?ng hoài bão c?a chàng thanh niên tr? tu?i: nh?ng k?t giao, nh?ng m?i quan h?, t?ng bu?c thâm nh?p chính tru?ng, h?c cách d?i nhân x? th?, xây d?ng d?ng, lèo lái d?t nu?c vu?t qua nh?ng khó khan. T?p 1 k?t thúc ? th?i di?m Singapore tuyên b? d?c l?p nam 1965, sau khi tách ra t? Liên bang Malaysia, cung là lúc dánh d?u m?t c?t m?c quan tr?ng trong quá trình hình thành suy nghi, tính cách c?a ông Lý. Nh?ng bu?c di “buon ch?i” c?a m?t nhà lãnh d?o nang d?ng du?c t? l?i trong cu?n sách cung giúp ngu?i d?c có thêm m?t góc nhìn v? tình hình th? gi?i th?i Chi?n tranh L?nh, phong trào không liên k?t, M?, Anh, Nga, Trung Qu?c và các cu?ng qu?c khác ? th?i di?m còn dang “?n tàng” gi?a hai bên màn s?t; v? Liên minh châu Âu th?i k? hình thành, v? kh?i Th?nh vu?ng chung, và nh?ng liên minh, hi?p u?c khác. Lý Quang Di?u vi?t trong t?p 2 – “T? th? gi?i th? ba vuon lên th? nh?t”, xu?t b?n nam 1999: “N?u Singapore là m?t d?a tr?, tôi t? hào vì dã cham sóc và nuôi du?ng d?a tr? ?y”. Nam 1965, nhà nu?c Singapore non tr? giành d?c l?p, và s? t?n t?i c?a qu?c d?o nh? bé lúc dó r?t mong manh. T?ng là thu?c d?a c?a Vuong qu?c Anh v?i vai trò là c?ng giao thuong, Singapore nay tr? thành qu?c gia hi?n d?i ? châu Á, n?m trong tay hãng hàng không l?n nh?t th? gi?i, sân bay l?n, c?ng thuong m?i dông dúc nh?t, và m?c thu nh?p bình quân d?u ngu?i cao th? 4 th? gi?i. Câu chuy?n v? s? chuy?n d?i c?a Singapore du?c k? m?t cách lôi cu?n, và cung gây tranh cãi. Ð?t nu?c Singapore sinh ra t? s? tan rã ch? d? th?c dân, sau s? tàn phá c?a Chi?n tranh th? gi?i th? 2, tình tr?ng dói nghèo ph? bi?n, s? r?i lo?n sau s? rút lui c?a l?c lu?ng nu?c ngoài. Singapore hi?n dang du?c ca ng?i là m?t thành ph? c?a tuong lai. Hi?n tu?ng l?ch s? phi thu?ng này du?c k? b?i 1 ngu?i không ch? s?ng qua t?t c? các giai do?n khó khan dó, mà chính là nhân v?t ki?n t?o qu?c gia, m? du?ng cho d?t nu?c. Cu?n sách du?c vi?t d?a trên nh?ng ghi chú t? m? c?a ông, cung nhu các gi?y t? c?a chính ph? chua du?c công b?, và nh?ng h? so chính th?c c?a chính ph? tru?c dây. Ông nêu ra nh?ng n? l?c phi thu?ng d? duy trì s? t?n t?i c?a d?o qu?c nh? bé ? Ðông Nam Á. Ông gi?i thích cách ông và các thành viên chính ph? d?p t?t m?i de d?a t? bên ngoài t?i an ninh c?a nhà nu?c non tr? này, và b?t d?u quá trình gian kh? xây d?ng d?t nu?c: xây d?ng h? th?ng du?ng sá, co s? h? t?ng, t? vùng d?t ch? y?u là d?m l?y; xây d?ng l?c lu?ng quân d?i t? ngu?n dân s? nh? bé, n?n phân bi?t ch?ng t?c ph? bi?n, chia r? ý th?c h?; lo?i b? v?n d? tham nhung còn t?n t?i t? th?i thu?c d?a; cung c?p h? th?ng nhà ? xã h?i; thành l?p hãng hàng không và sân bay qu?c gia. Ông cung vi?t m?t cách th?ng th?n v? cách ti?p c?n s?c bén c?a mình d? lo?i b? d?i th? chính tr? và nh?ng ngu?i có quan di?m không chính th?ng v? nhân quy?n, dân ch?,… nh?m “luôn dúng khuôn m?u, không ch? v? m?t chính tr?”. Cung trong cu?n sách, Lý Quang Di?u kh?c h?a chân dung ngu?i dàn bà thép Margaret Thatcher và Ronald Reagan, Giang Tr?ch Dân, George Bush và Ð?ng Ti?u Bình. Ông vén b?c màn bí m?t v? gia dình, vi?t m?t cách c?n tr?ng và yêu thuong v? v? ông và ngu?i con trai Lý Hi?n Long. Ông', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_35053_1.jpg', 602, 2023, 50, 0, N'Th? Gi?i', N'8935270704322', 28, 1, 61, 7, CAST(273700.00 AS Decimal(18, 2)))
