INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (517, N'Tr? V? - Ph?n 1: Châu Âu', N'Phan Công Thi?t', N'CÔNG TY C? PH?N SÁCH OMEGA VI?T NAM', CAST(80000.00 AS Decimal(18, 2)), N'Tr? V? - Ph?n 1: Châu Âu Chúng ta s?ng trong m?t th? gi?i d?y s? hoài nghi và s? hãi? Chúng ta có r?t nhi?u lý do d? không di du l?ch nu?c ngoài: Thi?u ti?n, thi?u gi?y t?, s? nguy hi?m…. Cu?n h?i ký 173 ngày tr? v? chính là câu tr? l?i c?a Phan dành t?i nh?ng b?n tr? có u?c mo khám phá th? gi?i nhung không có nhi?u kinh phí. Anh dã s? d?ng r?t nhi?u gi?i pháp d? di du l?ch t? Pháp tr? v? Vietnam trong di?u ki?n eo h?p v? tài chính nhung không làm m?t di s? d?p d? c?a hành trình. Ph?n 1 : Châu Âu v?i tên g?i là d?c l?p-t? do-h?nh phúc là m?t l?i tuyên b? hùng h?n cho tu?i thanh xuân, cho nh?ng b?n có khát khao, dam mê khám phá th? gi?i, khám phá van hoá qu?c t?. Qua các ?ng d?ng Couchesurfing ( xin ? nh? ), Workaway ( làm tình nguy?n) và Hichhiking ( xin di du?ng). Phan dã có r?t nhi?u câu chuy?n thú v? và chân th?c trên hành trình t? Pháp tr? v? Vietnam. Ðó là cu?n nh?t ký du?c ghi chép l?i m?t cách chân th?c t?ng ngày trên hành trình. Sau m?i ngày, Phan l?i ghi chép nh?ng gì dã x?y ra, câu ch? và m?ch van g?n gui, không trau chu?t vì nó du?c ghi trong su?t hành trình, nh?m tôn tr?ng nh?ng c?m xúc chân th?t nh?t và góc nhìn c?a anh t?i th?i di?m dó v? nh?ng con ng?oi, nh?ng câu chuy?n trong van hoá h?i nh?p qu?c t?. Kh?i ngu?n t? Pháp, Phan d?ch chuy?n lên Ba Lan và di d?c d?t nu?c Ph?n Lan xinh d?p, di phu?t qua phía B?c c?a Nauy , tr? v? Helsinki d? di tàu qua Thu? Ði?n… Phan dã truy?n t?i v? m?t chuy?n di di?n ra v?i nhi?u c?m xúc t? nhiên, không trói bu?c b?i nh?ng k? ho?ch, Phan d? cho m?i ngu?i hoà vào chuy?n hành trình c?a mình, vào tâm h?n c?a Anh, vào các ý ki?n da chi?u v? nhi?u ch? d? c?a cu?c s?ng. Ðó là nh?ng câu chuy?n don gi?n, không có k?t c?u, không có c?u trúc b? c?c, không có di?m d?u và di?m k?t thúc, nh? nhàng và sâu s?c, g?n gui và có ý nghia, s? d?ng l?i cu?i cùng c?a cu?n hành trình có l? dó là s? don gi?n, s? tích c?c, s? d?p d? nhu b?n ch?t c?a cu?c s?ng này mà tác gi? mu?n ch?ng minh cho m?i ngu?i th?y. Ðó là thông di?p mà anh mu?n truy?n t?i cho nh?ng th? h? tr? hon : Hãy dám di ra, th? gi?i bên ngoài d?y d? s? t?t d?p n?u b?n x?ng dáng!', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043929973.jpg', 324, 2023, 50, 0, N'Th? Gi?i', N'9786043929973', 30, 1, 63, 11, CAST(56000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (518, N'Danh Tác Vi?t Nam - Nh?ng Ngày Tho ?u (In Theo B?n C?a NXB Ð?i Nay Nam 1940)', N'Nguyên H?ng', N'Nhà Sách Minh Th?ng', CAST(40000.00 AS Decimal(18, 2)), N'Danh Tác Vi?t Nam - Nh?ng Ngày Tho ?u (In Theo B?n C?a NXB Ð?i Nay Nam 1940) Tác ph?m “Nh?ng ngày tho ?u” c?a Nguyên H?ng là m?t trong nh?ng h?i ký van h?c n?i b?t trong n?n van h?c Vi?t Nam hi?n d?i. Du?i dây là phân tích nh?ng di?m hay và d?c s?c c?a tác ph?m: 1. Tình c?m chân th?t, sâu s?c 2. Ph?n ánh hi?n th?c xã h?i 3. Ngh? thu?t k? chuy?n và miêu t? tinh t? 4. Giá tr? nhân d?o sâu s?c 5. T? truy?n giàu giá tr? van h?c và tu tu?ng “Nh?ng ngày tho ?u” không ch? là m?t tác ph?m t? truy?n mà còn là l?i kêu c?u c?a m?t tâm h?n non n?t gi?a m?t xã h?i d?y d?nh ki?n và thi?u tình ngu?i. V?i van phong giàu c?m xúc, l?i k? chuy?n t? nhiên và giá tr? nhân van sâu s?c, tác ph?m x?ng dáng là m?t tác ph?m kinh di?n c?a van h?c Vi?t Nam.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935236437066_1.jpg', 152, 2025, 50, 0, N'Van H?c', N'8935236437066', 30, 1, 63, 30, CAST(28000.00 AS Decimal(18, 2)))
